/// Type-check `(:wat::kernel::require-wire-address x)` — 293.W.2f.
///
/// The process-runner door. Unifies the argument's transport marker against
/// `Wire`. A `Handle<Shared>` / `Address<_,_,Shared>` is a TypeMismatch
/// naming Shared vs Wire. 2-arg Address (T unknown) and non-address data
/// fields are residuals (allowed). Result type is the argument's type.
/// Runtime is identity.
fn infer_require_wire_address(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::require-wire-address";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 1 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch {
                callee: OP.into(),
                expected: 1,
                got: args.len(),
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        let t = fresh.fresh();
        return CheckResult::partial_with(t, local_errors);
    }

    let got_ty = match infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
        Some(t) => t,
        None => {
            let t = fresh.fresh();
            return CheckResult::partial_with(t, local_errors);
        }
    };
    let got_reduced = reduce(&apply_subst(&got_ty, subst), subst, env.types());
    if let Some(marker) = transport_marker(&got_reduced) {
        let marker = reduce(&apply_subst(&marker, subst), subst, env.types());
        if !is_wire_marker(&marker) {
            // T unknown (a unification var) unifies with Wire — residual.
            if matches!(marker, TypeExpr::Var(_)) {
                let _ = unify(&marker, &wire_marker(), subst, env.types());
            } else {
                local_errors.push(CheckError {
                    span: args[0].span().clone(),
                    kind: CheckErrorKind::TypeMismatch {
                        callee: OP.into(),
                        param: "addr".into(),
                        expected: "Address<S,R,Wire>".into(),
                        got: format_type(&got_reduced),
                    },
                });
            }
        }
    }
    if local_errors.is_empty() {
        CheckResult::ok(got_ty)
    } else {
        CheckResult::partial_with(got_ty, local_errors)
    }
}

/// Extract the transport marker T from `Address<S,R,T>` or from a parametric
/// type whose last argument is Shared/Wire (Handle<Shared>, Handle<K,V,Wire>).
/// 2-arg Address and unrelated parametrics (Vector<i64>, …) yield None.
fn transport_marker(ty: &TypeExpr) -> Option<TypeExpr> {
    match ty {
        TypeExpr::Parametric { head, args } if head == "wat::kernel::Address" && args.len() == 3 => {
            Some(args[2].clone())
        }
        TypeExpr::Parametric { args, .. } if !args.is_empty() => {
            let last = args.last().cloned().expect("non-empty");
            if is_shared_marker(&last) || is_wire_marker(&last) || matches!(last, TypeExpr::Var(_)) {
                Some(last)
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Type-check `(:wat::kernel::serve-dispatch-op clients body)` — arc 278 RST
/// stone. `clients` is inferred for internal-consistency/error-surfacing only
/// (`poll'`'s `listener`-arg discipline — checked, but its type is never
/// unified with anything, since `serve-dispatch-op'` is ∀-generic over the
/// service's own `Peer'<S,R>` element type and has no reason to pin it down).
/// `body`'s inferred type IS the form's own type — the SAME do-style
/// passthrough `infer_do` uses for its final arg (see that function): this
/// primitive is a transparent runtime wrapper around what used to be a bare
/// `:wat::core::match`, so it must be transparent to the type checker too.
fn infer_serve_dispatch_op(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::serve-dispatch-op";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 2 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch { callee: OP.into(), expected: 2, got: args.len() },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        return CheckResult::errs(local_errors);
    }
    // clients: checked for error coverage only — type not further constrained.
    let _ = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    // body: its inferred type IS the form's type (do-style passthrough).
    let val = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    match val {
        Some(ty) => if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) },
        None => CheckResult::errs(local_errors),
    }
}

/// Arc 278 Stone 2 (Option A) — `(:wat::kernel::retag-op op :<surface>::Op
/// :<service>::Op)` → `<service>::Op`.
///
/// The `<service>::Op` superset RE-TAG. Three args: the op value (inferred for
/// error coverage only — the runtime rewrite does not constrain it here), the
/// surface Op type-keyword (the runtime discriminator; parsed/validated as a
/// type keyword), and the service Op type-keyword. The result type is the
/// service Op (arg[2]) — the same "return the type a keyword literal names"
/// pattern as `self-peer`. Runtime behavior is in `eval_retag_op`.
fn infer_retag_op(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::retag-op";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 3 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: OP.into(), expected: 3, got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        return CheckResult::partial_with(fresh.fresh(), local_errors);
    }
    // op: inferred for error coverage; its type is not further constrained.
    let _ = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    // surface Op (arg[1]): validate as a type keyword (the runtime discriminator).
    let _surface_ty = parse_peer_pair_type_arg(&args[1], OP, &mut local_errors, fresh);
    // service Op (arg[2]): the result type.
    let service_ty = parse_peer_pair_type_arg(&args[2], OP, &mut local_errors, fresh);
    if local_errors.is_empty() { CheckResult::ok(service_ty) } else { CheckResult::partial_with(service_ty, local_errors) }
}

// PARTITION — CLAUSE vs INTRINSIC: `infer_select_prime` is INTRINSIC (projective).
// I,O flow from Vector<peer<I,O>>'s element peer type into the return ServiceEvent<I,O,A>.
